/* ===== permissions reminder: camera / microphone / notifications ===== */
(()=>{
const $=id=>document.getElementById(id);
const box=$("permPrompt");if(!box)return;
const ITEMS=[{k:"camera",ar:"الكاميرا",en:"Camera"},{k:"microphone",ar:"الميكروفون",en:"Microphone"},{k:"notifications",ar:"الإشعارات",en:"Notifications"}];
const APP=["home","chat","settings","games","ludoGame","peerProfile"];
const isAr=()=>document.documentElement.lang!=="en";
const T=(a,e)=>isAr()?a:e;
let sig="",busy=false;
async function stateOf(k){
  try{
    if(k==="notifications"){
      if(!("Notification" in window))return "unsupported";
      const p=Notification.permission;return p==="default"?"prompt":p;
    }
    if(!navigator.mediaDevices||!navigator.permissions)return "unknown";
    return (await navigator.permissions.query({name:k})).state;
  }catch{return "unknown"}
}
const loggedIn=()=>APP.some(id=>$(id)&&!$(id).classList.contains("hidden"));
const blocked=()=>["call","captureDialog","loginRequest","incoming"].some(id=>$(id)&&!$(id).classList.contains("hidden"));
const snoozed=()=>{try{return sessionStorage.getItem("lr.permLater")==="1"}catch{return false}};
async function check(){
  if(busy)return;
  const st=await Promise.all(ITEMS.map(i=>stateOf(i.k)));
  const need=ITEMS.filter((i,n)=>st[n]==="prompt"||st[n]==="denied");
  if(!need.length||!loggedIn()||snoozed()||blocked()){box.classList.add("hidden");sig="";return}
  const s=st.join(",")+"|"+isAr();
  if(s!==sig){sig=s;render(st)}
  $("notificationPrompt")?.classList.add("hidden");
  box.classList.remove("hidden");
}
function render(st){
  $("permTitle").textContent=T("فعّل الأذونات عشان التطبيق يشتغل كامل","Turn on permissions so everything works");
  $("permLead").textContent=T("الكاميرا والمايك والإشعارات لازم تبقى مفعّلة عشان المكالمات والصور والتنبيهات.","Camera, microphone and notifications are needed for calls, photos and alerts.");
  const ul=$("permList");ul.textContent="";
  ITEMS.forEach((i,n)=>{
    const s=st[n];if(s==="unknown"||s==="unsupported")return;
    const li=document.createElement("li");li.className="permItem "+(s==="granted"?"ok":s==="denied"?"bad":"ask");
    const name=document.createElement("strong");name.textContent=T(i.ar,i.en);
    const tag=document.createElement("span");
    tag.textContent=s==="granted"?T("مفعّل","On"):s==="denied"?T("مقفول","Blocked"):T("محتاج تفعيل","Needs permission");
    li.append(name,tag);ul.appendChild(li);
  });
  const denied=ITEMS.filter((i,n)=>st[n]==="denied");
  const help=$("permHelp");
  if(denied.length){
    const names=denied.map(i=>T(i.ar,i.en)).join(T(" و",", "));
    help.textContent=T(
      "الإذن مقفول من إعدادات الجهاز، والموقع مبيقدرش يفتحه لوحده. دوس على أيقونة القفل (أو ⋮ / الإعدادات) جنب عنوان الموقع ← الأذونات ← اختار «سماح» لـ: "+names+". ولو بتستخدمه كتطبيق: إعدادات الهاتف ← التطبيقات ← الأذونات. وبعدها ارجع هنا وهيتحدّث لوحده.",
      "These are blocked in your device settings and the site cannot turn them on by itself. Tap the lock icon (or ⋮ / Settings) next to the address bar → Permissions → Allow: "+names+". If you installed it as an app: phone Settings → Apps → Permissions. Then come back here; this updates by itself.");
    help.classList.remove("hidden");
  }else help.classList.add("hidden");
  const canAsk=ITEMS.some((i,n)=>st[n]==="prompt");
  $("permAllow").textContent=canAsk?T("تفعيل الأذونات","Enable permissions"):T("تحقق تاني","Check again");
  $("permLater").textContent=T("لاحقًا","Later");
}
async function allow(){
  busy=true;$("permAllow").disabled=true;
  try{
    const st=Object.fromEntries(await Promise.all(ITEMS.map(async i=>[i.k,await stateOf(i.k)])));
    const wantCam=st.camera==="prompt",wantMic=st.microphone==="prompt";
    if((wantCam||wantMic)&&navigator.mediaDevices?.getUserMedia){
      let got=false;
      try{(await navigator.mediaDevices.getUserMedia({video:wantCam,audio:wantMic})).getTracks().forEach(t=>t.stop());got=true}catch{}
      if(!got&&wantCam&&wantMic){for(const c of[{audio:true},{video:true}]){try{(await navigator.mediaDevices.getUserMedia(c)).getTracks().forEach(t=>t.stop())}catch{}}}
    }
    if(st.notifications==="prompt"){try{await Notification.requestPermission()}catch{}}
    if("Notification" in window&&Notification.permission==="granted")$("notifEnable")?.click();
  }finally{busy=false;$("permAllow").disabled=false;sig="";check()}
}
$("permAllow").onclick=allow;
$("permLater").onclick=()=>{try{sessionStorage.setItem("lr.permLater","1")}catch{}box.classList.add("hidden")};
for(const ev of["visibilitychange","focus"])addEventListener(ev,()=>{if(!document.hidden)check()});
setInterval(check,2500);
setTimeout(check,800);
/* طلب كل الأذونات أول ما الموقع يتفتح؛ ولو المتصفح محتاج لمسة (iOS/Firefox/Safari) بنطلبها مع أول لمسة */
let autoTried=false,tapTried=false;
async function autoAsk(){
  if(busy||blocked())return false;
  const st=await Promise.all(ITEMS.map(i=>stateOf(i.k)));
  if(!st.includes("prompt"))return false;
  await allow();return true;
}
setTimeout(()=>{if(autoTried)return;autoTried=true;autoAsk()},600);
addEventListener("pointerdown",()=>{if(tapTried)return;tapTried=true;autoAsk()},{capture:true});
})();
/* سحب نافذة كاميرتي الصغيرة في المكالمة (إصبع أو ماوس) */
(()=>{
  const pip=document.getElementById("localVid"),call=document.getElementById("call");
  if(!pip||!call)return;
  const GAP=8;let drag=null;
  /* النافذة تفضل بين الشريط العلوي وصف الأزرار، عشان ما تقعش ورا الأزرار وتبقى مش قابلة للمسك */
  const place=(x,y)=>{
    const c=call.getBoundingClientRect(),w=pip.offsetWidth,h=pip.offsetHeight;
    const ctrl=call.querySelector(".callControls"),bar=call.querySelector(".callTop");
    const cr=ctrl&&ctrl.getBoundingClientRect(),br=bar&&bar.getBoundingClientRect();
    const minY=Math.max(GAP,br&&br.height?br.bottom-c.top+GAP:GAP);
    let maxY=c.height-h-GAP;
    if(cr&&cr.height)maxY=Math.min(maxY,cr.top-c.top-h-GAP);
    maxY=Math.max(minY,maxY);
    pip.style.left=Math.max(GAP,Math.min(c.width-w-GAP,x))+"px";
    pip.style.top=Math.max(minY,Math.min(maxY,y))+"px";
  };
  pip.addEventListener("pointerdown",e=>{
    if(e.pointerType==="mouse"&&e.button!==0)return;
    const c=call.getBoundingClientRect(),r=pip.getBoundingClientRect();
    drag={id:e.pointerId,dx:e.clientX-r.left,dy:e.clientY-r.top};
    pip.style.right="auto";pip.style.bottom="auto";
    pip.style.left=(r.left-c.left)+"px";pip.style.top=(r.top-c.top)+"px";
    pip.classList.add("dragging");
    try{pip.setPointerCapture(e.pointerId)}catch{}
    e.preventDefault();
  });
  pip.addEventListener("pointermove",e=>{
    if(!drag||e.pointerId!==drag.id)return;
    const c=call.getBoundingClientRect();
    place(e.clientX-c.left-drag.dx,e.clientY-c.top-drag.dy);
  });
  const end=e=>{if(!drag||(e&&e.pointerId!==drag.id))return;drag=null;pip.classList.remove("dragging")};
  pip.addEventListener("pointerup",end);pip.addEventListener("pointercancel",end);pip.addEventListener("lostpointercapture",end);
  /* لما المكالمة تخلص، النافذة ترجع لمكانها الأصلي */
  new MutationObserver(()=>{if(call.classList.contains("hidden")){drag=null;pip.classList.remove("dragging");pip.style.left=pip.style.top=pip.style.right=pip.style.bottom=""}}).observe(call,{attributes:true,attributeFilter:["class"]});
  /* لو الشاشة اتقلبت أو اتغير حجمها، نخلّي النافذة جوه الشاشة */
  addEventListener("resize",()=>{if(pip.style.left)place(parseFloat(pip.style.left)||0,parseFloat(pip.style.top)||0)});
})();
